package main

import (
	"fmt"
)

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	var n int
	fmt.Scan(&n)

	a := make([]int, 100)
	count := 0

	for i := 0; i < n; i++ {
		fmt.Scan(&a[i])
		count += a[i]
	}

	temp := a[0]
	if n > 1 {
		for i := 0; i < n; i++ {
			temp = max(temp, a[i])
		}
	}

	ans := 0
	for i := 0; ; i++ {
		k := temp + i
		if (n*k - count) > count {
			ans = k
			break
		}
	}

	fmt.Print(ans)
}

